/* Preview navigation visits operator-visible steps, skipping automatic decisions. */
const backRenderBase=renderSim;
renderSim=function(){backRenderBase();if(!sim)return;const n=sim.nodes.find(n=>n.id===sim.id);if(!n||n.type==='condition')return;sim.visits??=[];if(sim.visits.at(-1)?.id!==sim.id)sim.visits.push({id:sim.id,answers:structuredClone(sim.answers),path:structuredClone(sim.path),otherAnswers:structuredClone(sim.otherAnswers||{})});const phone=document.querySelector('.phone');if(!phone||phone.querySelector('#preview-back'))return;phone.insertAdjacentHTML('beforeend',`<button id="preview-back" style="width:100%;margin-top:12px" onclick="simPrevious()" ${sim.visits.length<2?'disabled':''}>← Previous step</button>`)};
function simPrevious(){if(!sim||sim.visits?.length<2)return;sim.visits.pop();const previous=sim.visits.at(-1),saved=structuredClone(sim.answers[previous.id]),other=sim.otherAnswers?.[previous.id];sim.id=previous.id;sim.answers=structuredClone(previous.answers);sim.path=structuredClone(previous.path);sim.otherAnswers=structuredClone(previous.otherAnswers||{});renderSim();const otherField=document.querySelector('#simother');if(otherField&&other!==undefined)otherField.value=other;const el=document.querySelector('#simvalue');if(el&&el.type!=='file'&&saved!==undefined)el.value=Array.isArray(saved)?'':String(saved);document.querySelectorAll('.simcheck').forEach(e=>e.checked=Array.isArray(saved)&&saved.includes(e.value));if(el?.type==='file'){const err=document.querySelector('#simerror');if(err)err.textContent='Choose the proof files again when revisiting this step.'}}
